#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
GH_REPO="${GH_REPO:-}" # owner/repo for gh writes; empty = infer from cwd
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# _gh_ready — gh installed and authenticated?
_gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# preflight_gh — prove gh can actually reach the repo BEFORE any stage asks for
# a credential. A token that cannot resolve the repo must fail here, not after
# the human has minted a password. Call once, right after banner.
preflight_gh() {
  local out="" rc=0
  if ! command -v gh >/dev/null 2>&1; then
    warn "gh not installed — secrets will be skipped"; return 1
  fi
  if ! gh auth status >/dev/null 2>&1; then
    warn "gh not authenticated — run: gh auth login"; return 1
  fi
  if [[ -n "$GH_REPO" ]]; then
    out=$(gh repo view "$GH_REPO" --json nameWithOwner 2>&1 >/dev/null) || rc=$?
  else
    out=$(gh repo view --json nameWithOwner 2>&1 >/dev/null) || rc=$?
  fi
  (( rc == 0 )) && return 0
  warn "gh cannot reach ${GH_REPO:-the current repo}: ${out%%$'\n'*}"
  note "fix the token scope now, or every secret below will be skipped"
  return 1
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh, targeting
# $GH_REPO when set. Reports gh's own error rather than hiding it: a silent
# "skipped" reads as done and is how a wizard finishes with nothing written.
set_secret() {
  local name="$1" value="$2" err="" rc=0
  if ! _gh_ready; then
    err="gh not installed or not authenticated"; rc=1
  elif [[ -n "$GH_REPO" ]]; then
    err=$(printf '%s' "$value" | gh secret set "$name" --repo "$GH_REPO" 2>&1 >/dev/null) || rc=$?
  else
    err=$(printf '%s' "$value" | gh secret set "$name" 2>&1 >/dev/null) || rc=$?
  fi
  if (( rc == 0 )); then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
    return 0
  fi
  err="${err%%$'\n'*}"; [[ -n "$err" ]] || err="gh exited $rc"
  SKIPPED+=("GitHub secret $name — $err")
  warn "skipped GitHub secret $name: $err"
  return 0
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2" err="" rc=0
  if ! _gh_ready; then
    err="gh not installed or not authenticated"; rc=1
  elif [[ -n "$GH_REPO" ]]; then
    err=$(gh variable set "$name" --repo "$GH_REPO" --body "$value" 2>&1 >/dev/null) || rc=$?
  else
    err=$(gh variable set "$name" --body "$value" 2>&1 >/dev/null) || rc=$?
  fi
  if (( rc == 0 )); then
    printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
    return 0
  fi
  err="${err%%$'\n'*}"; [[ -n "$err" ]] || err="gh exited $rc"
  SKIPPED+=("GitHub variable $name — $err")
  warn "skipped GitHub variable $name: $err"
  return 0
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# Braces + exit: bash parses the whole block before running it, so saving an
# edit to this file mid-run can't make bash resume at a stale byte offset.
{
TOTAL_STAGES=9
TOTAL_MINUTES=40

# Nothing is written locally: secrets go from a hidden prompt straight over ssh
# stdin (never argv) or into gcp-setup.sh's own hidden prompt.
ENV_FILE=/nonexistent
PROJECT=bcns-connect
PROJECT_NUMBER=274953429391
HUB=https://connect.bcn-services.com
ENVF=/srv/connect/env
REPO_ROOT="$(cd "$(dirname "$0")" && pwd)"

banner "bcns Connect — Google (Meet + Drive) go-live"
warn "Chrome: Work Profile, nseluga@bcn-services.com, project $PROJECT."
note "Design + evidence: docs/architecture/chunk7-google-flow.md. Nothing goes live until stage 7."
[[ -t 0 ]] || { warn "run this in a terminal (it reads hidden input)."; exit 1; }
HUB_MISSING=0

code=$(curl -s --max-time 10 -o /dev/null -w '%{http_code}' "$HUB/api/oauth/drive/start" || true)
if [[ "$code" == "404" ]]; then
  warn "$HUB/api/oauth/drive/start is 404: the hub PR (#134) isn't deployed yet."
  confirm "Continue anyway (Google console stages only; droplet + gate stages skip)?" || exit 1
  HUB_MISSING=1
elif [[ "$code" == "405" ]]; then
  note "hub route present (GET 405; it only takes POST)."
else
  note "hub route check inconclusive (HTTP $code); confirm #134 is deployed."
fi

stage "Consent screen branding + audience" 4
open_url "https://console.cloud.google.com/auth/branding?project=$PROJECT"
step "App name: bcns Connect. User support + developer contact: nseluga@bcn-services.com"
step "Homepage https://bcn-services.com · Privacy https://bcn-services.com/privacy · Terms https://bcn-services.com/terms"
step "Authorized domain: bcn-services.com"
open_url "https://console.cloud.google.com/auth/audience?project=$PROJECT"
step "User type External, publishing status In production (not Testing: Testing kills refresh tokens after 7 days)."
pause

stage "Data access: drive.readonly only" 1
open_url "https://console.cloud.google.com/auth/scopes?project=$PROJECT"
step "Restricted scopes lists exactly .../auth/drive.readonly. Nothing under sensitive/non-sensitive is needed."
note "The 'requires verification' banner is expected: unverified works up to 100 users, \$0."
pause

stage "Prod OAuth client (Web)" 5
open_url "https://console.cloud.google.com/auth/clients/create?project=$PROJECT"
step "Web application. Name: bcns Connect hub"
step "Authorized JavaScript origins: $HUB"
step "Authorized redirect URIs (both):"
say  "    $HUB/api/oauth/meet/callback"
say  "    $HUB/api/oauth/drive/callback"
step "Create. Copy both values below; the secret is shown once."
GOOGLE_CLIENT_ID=""
until [[ "$GOOGLE_CLIENT_ID" =~ ^[0-9]+-[A-Za-z0-9_]+\.apps\.googleusercontent\.com$ ]]; do
  ask GOOGLE_CLIENT_ID "Client ID (<digits>-<chars>.apps.googleusercontent.com):"
done
GOOGLE_CLIENT_SECRET=""
until [[ -n "$GOOGLE_CLIENT_SECRET" ]]; do ask_secret GOOGLE_CLIENT_SECRET "Client secret (hidden):"; done

stage "Prod Picker API key" 3
open_url "https://console.cloud.google.com/apis/credentials?project=$PROJECT"
step "Create credentials → API key, then edit it. Name: bcns Connect Picker"
step "Application restrictions: Websites → $HUB/*  and  https://docs.google.com/*"
step "API restrictions: Google Picker API only. Save."
GOOGLE_PICKER_API_KEY=""
until [[ -n "$GOOGLE_PICKER_API_KEY" ]]; do ask_secret GOOGLE_PICKER_API_KEY "API key (hidden):"; done

stage "Droplet: hub env + restart (gate stays closed)" 5
if (( HUB_MISSING )); then
  warn "hub PR not deployed: skipping the droplet and the gate. Re-run once #134 is live."
  SKIPPED+=("droplet env + gate: re-run ./google-flow-wizard.sh after #134 deploys")
  finish; exit
fi
DROPLET_SSH="${DROPLET_SSH:-root@146.190.138.141}"
SSH_KEY="${SSH_KEY:-$HOME/.ssh/id_ed25519_bcns}"
ask DROPLET_SSH "ssh target [$DROPLET_SSH]:"; DROPLET_SSH="${DROPLET_SSH:-root@146.190.138.141}"
ask SSH_KEY "ssh key [$SSH_KEY]:"; SSH_KEY="${SSH_KEY:-$HOME/.ssh/id_ed25519_bcns}"; SSH_KEY="${SSH_KEY/#\~/$HOME}"
_ssh() { ssh -i "$SSH_KEY" -o IdentitiesOnly=yes -o BatchMode=yes "$DROPLET_SSH" "$@"; }
dssh() { _ssh -n "$@"; }
hub_pid() { dssh 'systemctl show -p MainPID --value bcns-app@connect' | tr -d '[:space:]'; }
gate() { dssh "grep -E '^OAUTH_APPROVED_SOURCES=' $ENVF | tail -n1 | cut -d= -f2-" | tr -d '[:space:]'; }
dssh true || { warn "ssh to $DROPLET_SSH failed; fix and re-run."; exit 1; }
note "current keys in $ENVF (names only):"
dssh "grep -oE '^[A-Z_]+=' $ENVF | tr -d '=' | paste -sd' ' -"
GATE_BEFORE="$(gate || true)"
note "OAUTH_APPROVED_SOURCES now: ${GATE_BEFORE:-<unset>} (this stage leaves it alone)"
confirm "Replace any GOOGLE_* lines in $ENVF with the 4 new ones and restart the hub?" || exit 1
PID_BEFORE="$(hub_pid)"
printf 'GOOGLE_CLIENT_ID=%s\nGOOGLE_CLIENT_SECRET=%s\nGOOGLE_PICKER_API_KEY=%s\nGOOGLE_CLOUD_PROJECT_NUMBER=%s\n' \
  "$GOOGLE_CLIENT_ID" "$GOOGLE_CLIENT_SECRET" "$GOOGLE_PICKER_API_KEY" "$PROJECT_NUMBER" \
  | _ssh "f=$ENVF; sed -i '/^GOOGLE_\(CLIENT_ID\|CLIENT_SECRET\|PICKER_API_KEY\|CLOUD_PROJECT_NUMBER\)=/d' \$f \
      && { [ -z \"\$(tail -c1 \$f)\" ] || echo >> \$f; } && cat >> \$f && sudo -n systemctl restart bcns-app@connect"
sleep 3
PID_AFTER="$(hub_pid)"
dssh "grep -oE '^GOOGLE_[A-Z_]+=' $ENVF | tr -d '=' | paste -sd' ' -"
[[ "$PID_AFTER" != "$PID_BEFORE" && "$PID_AFTER" != "0" ]] \
  && printf '  %s✓%s hub restarted: pid %s → %s\n' "$GREEN" "$RESET" "$PID_BEFORE" "$PID_AFTER" \
  || warn "pid $PID_BEFORE → $PID_AFTER: not a clean restart. Check: journalctl -u bcns-app@connect -n 50"
note "expected: the 4 GOOGLE_* names above; Meet/Drive cards still say 'Request connection'."
pause

stage "Cloud Run worker: client id + secret" 5
note "Needs the worker PR (#135) merged and deployed, and gcloud logged in as a project Owner."
warn "This is the worker's project (the existing bcns one in platform/docs/deploy-worker.md), NOT bcns-connect."
GCP_PROJECT="${GCP_PROJECT:-}"; GCP_REGION="${GCP_REGION:-us-east4}"
until [[ -n "$GCP_PROJECT" ]]; do ask GCP_PROJECT "Worker GCP project id:"; done
ask GCP_REGION "Worker region [us-east4]:"; GCP_REGION="${GCP_REGION:-us-east4}"
SETUP="$REPO_ROOT/platform/scripts/gcp-setup.sh"
if gcloud secrets describe GOOGLE_CLIENT_SECRET --project "$GCP_PROJECT" >/dev/null 2>&1; then
  warn "Secret GOOGLE_CLIENT_SECRET already exists; gcp-setup.sh keeps it and won't ask."
  if confirm "Add the client secret you entered above as a new version?"; then
    printf '%s' "$GOOGLE_CLIENT_SECRET" | gcloud secrets versions add GOOGLE_CLIENT_SECRET \
      --project "$GCP_PROJECT" --data-file=- >/dev/null && note "new version added."
  fi
fi
if grep -q "6c. Google" "$SETUP" 2>/dev/null; then
  step "Runs gcp-setup.sh (idempotent, its own y/n per step). At 6c it asks for the secret (hidden) if none exists."
  if confirm "Run it now?"; then
    GCP_PROJECT="$GCP_PROJECT" GCP_REGION="$GCP_REGION" GOOGLE_CLIENT_ID="$GOOGLE_CLIENT_ID" bash "$SETUP" \
      || warn "gcp-setup.sh exited non-zero; the gate check below decides."
  fi
else
  warn "this checkout's gcp-setup.sh has no step 6c (worker PR not merged here); run it from a main checkout with #135."
fi
JOB_ENV="$(gcloud run jobs describe bcns-data-worker --project "$GCP_PROJECT" --region "$GCP_REGION" \
  --format='value(spec.template.spec.template.spec.containers[0].env[].name)' 2>/dev/null || true)"
WORKER_OK=0
[[ "$JOB_ENV" == *GOOGLE_CLIENT_ID* && "$JOB_ENV" == *GOOGLE_CLIENT_SECRET* ]] && WORKER_OK=1
(( WORKER_OK )) && printf '  %s✓%s job env has GOOGLE_CLIENT_ID + GOOGLE_CLIENT_SECRET\n' "$GREEN" "$RESET" \
  || warn "bcns-data-worker env lacks GOOGLE_CLIENT_ID/GOOGLE_CLIENT_SECRET (or describe failed)."
pause

stage "Open the gate: meet,drive" 3
if (( ! WORKER_OK )); then
  warn "Worker env not confirmed: every hub-connected row would fail its first refresh."
  ask GATE_FORCE "Type 'open anyway' to continue, Enter to stop:"
  [[ "${GATE_FORCE:-}" == "open anyway" ]] || { SKIPPED+=("gate: fix Cloud Run env, re-run"); finish; exit; }
fi
GATE_BEFORE="$(gate || true)"
GATE_NEW="$(printf '%s\n' ${GATE_BEFORE//,/ } meet drive | awk 'NF && !seen[$0]++' | paste -sd, -)"
[[ "$GATE_NEW" =~ ^[a-z,]+$ ]] || { warn "unexpected gate value '$GATE_NEW'; stopping."; exit 1; }
note "OAUTH_APPROVED_SOURCES: ${GATE_BEFORE:-<unset>} → $GATE_NEW"
if confirm "Write it and restart the hub? This makes Meet + Drive self-serve live."; then
  PID_BEFORE="$(hub_pid)"
  dssh "sed -i '/^OAUTH_APPROVED_SOURCES=/d' $ENVF && printf 'OAUTH_APPROVED_SOURCES=%s\n' '$GATE_NEW' >> $ENVF \
        && sudo -n systemctl restart bcns-app@connect"
  sleep 3
  dssh 'p=$(systemctl show -p MainPID --value bcns-app@connect)
        v=$(tr "\0" "\n" < /proc/$p/environ | grep "^OAUTH_APPROVED_SOURCES=" || true)
        echo "pid $p: ${v:-OAUTH_APPROVED_SOURCES unset}"'
  note "expected: $GATE_NEW on a pid other than $PID_BEFORE."
  open_url "$HUB"
  step "Meet and Drive cards now show Connect (signed in as an owner)."
  note "rollback:"
  say  "    ssh -i $SSH_KEY $DROPLET_SSH \"sed -i '/^OAUTH_APPROVED_SOURCES=/d' $ENVF && printf 'OAUTH_APPROVED_SOURCES=%s\\\\n' '$GATE_BEFORE' >> $ENVF && sudo -n systemctl restart bcns-app@connect\""
else
  SKIPPED+=("gate: OAUTH_APPROVED_SOURCES=$GATE_NEW in $ENVF + restart bcns-app@connect")
fi
pause

stage "Verification (read, don't submit yet)" 2
open_url "https://console.cloud.google.com/auth/verification?project=$PROJECT"
note "Free route: stay unverified under 100 users; owners click through Google's warning."
note "Submitting the restricted-scope review leads to a paid CASA assessment (AL1 from \$675, reassessed yearly). Submit only when ready to pay."
pause

stage "Clean-up (after a prod connect works)" 3
open_url "https://console.cloud.google.com/auth/clients?project=$PROJECT"
step "Delete OAuth client 'bcns Connect hub (local dev)'."
open_url "https://console.cloud.google.com/apis/credentials?project=$PROJECT"
step "Delete API key 'bcns Connect Picker (local dev)'."
open_url "https://console.cloud.google.com/iam-admin/settings?project=bcns-connect-511400"
step "Optional: shut down duplicate project bcns-connect-511400 (holds nothing)."
step "Optional: trash the Drive folder 'bcns google-flow test'."
pause

finish
exit
}
